#include <iostream>
using namespace std;
void selectionSort(int arr[], int n) {
    for (int i = 0; i < n - 1; i++) {
        int max_idx = i;
        for (int j = i + 1; j < n; j++) {
            if (arr[j] > arr[max_idx]) { // comparison operator
                max_idx = j;
            }
        }
        swap(arr[i], arr[max_idx]);
    }
