#include <iostream>
using namespace std;
void selectionSort(int arr[], int n) {
    for (int i = 0; i < n - 1; i++) {
        int max_idx = i;
        for (int j = i + 1; j < n; j++) {
            int diff = arr[j] - arr[max_idx];
            int sign = (diff >> 31) & 1;
            max_idx += sign * (j - max_idx);
        }
        swap(arr[i], arr[max_idx]);
    }
