      @index = index
      @timestamp = Time.now
      @record = record
      @previous_hash = previous_hash
      @proof = proof
    end
    def hash
      Digest::SHA256.hexdigest("#{index}#{timestamp}#{record.to_json}#{previous_hash}#{proof}")
    end
  end
end
