import java.util.*;
public class MatrixGenerator {
    public static void main(String[] args) {
        int[][] matrix = new int[5][5];
        Random rand = new Random();
        // Fill the matrix with random integers between -50 and 50
        for (int i = 0; i < 5; i++) {
            for (int j = 0; j < 5; j++) {
                matrix[i][j] = rand.nextInt(101) - 50;
            }
        }
        // Ensure each row and column has at least one negative and one positive number
        for (int i = 0; i < 5; i++) {
