            boolean hasNegative = false;
            for (int j = 0; j < 5; j++) {
                if (matrix[i][j] > 0) {
                    hasPositive = true;
                } else if (matrix[i][j] < 0) {
                    hasNegative = true;
                }
            }
            if (!hasPositive || !hasNegative) {
                // Swap a positive and negative number in the row
                int positiveIndex = rand.nextInt(5);
                int negativeIndex = rand.nextInt(5);
                while (matrix[i][positiveIndex] < 0) {
                    positiveIndex = rand.nextInt(5);
                }
                while (matrix[i][negativeIndex] > 0) {
                    negativeIndex = rand.nextInt(5);
                }
                int temp = matrix[i][positiveIndex];
                matrix[i][positiveIndex] = matrix[i][negativeIndex];
                matrix[i][negativeIndex] = temp;
            }
            hasPositive = false;
            hasNegative = false;
            for (int j = 0; j < 5; j++) {
                if (matrix[j][i] > 0) {
                    hasPositive = true;
                } else if (matrix[j][i] < 0) {
