        // Ensure the sum of the main diagonal is negative and the sum of the secondary diagonal is positive
        int sumMainDiagonal = 0;
        int sumSecondaryDiagonal = 0;
        for (int i = 0; i < 5; i++) {
            sumMainDiagonal += matrix[i][i];
            sumSecondaryDiagonal += matrix[i][4-i];
