#include <iostream>
#include <string>
using namespace std;
string extractAction(string sentence) {
  // split sentence into words
  string delimiter = " ";
  size_t pos = 0;
  string token;
  while ((pos = sentence.find(delimiter)) != string::npos) {
    token = sentence.substr(0, pos);
    sentence.erase(0, pos + delimiter.length());
  }
  // return last word
  return sentence;
}
int main() {
  string sentence = "The individual named Robert has recently engaged in the physical activity of running";
  string action = extractAction(sentence);
  cout << "The main action is: " << action << endl;
  // remove action from sentence
  sentence.erase(sentence.find(action), action.length());
  cout << "The remaining sentence is: " << sentence << endl;
  return 0;
}
