  code = c("AFG", "BGD", "BTN", "IND", "MDV", "NPL", "PAK", "LKA")
)
# Define a function to search for countries based on name or code
saarc_search <- function(query) {
  # Check if query matches a country name or code
  match <- saarc_countries[saarc_countries$country == query | saarc_countries$code == query, ]
  if (nrow(match) == 0) {
    # No match found
    print("No matching country found.")
  } else {
    # Match found
    print(match)
  }
}
# Test the search function
saarc_search("India") # should return India's ISO code (IND)
saarc_search("BGD") # should return Bangladesh's name
saarc_search("Nepal") # should return Nepal's ISO code (NPL)
# Define a function to filter countries based on a given criterion
saarc_filter <- function(criterion, value) {
  # Check if criterion is valid
  if (!(criterion %in% c("population", "area", "gdp"))) {
    print("Invalid criterion. Valid options are 'population', 'area', and 'gdp'.")
    return()
  }
  # Filter countries based on criterion
  if (criterion == "population") {
    filtered <- saarc_countries[saarc_countries$population == value, ]
  } else if (criterion == "area") {
    filtered <- saarc_countries[saarc_countries$area == value, ]
  } else if (criterion == "gdp") {
    filtered <- saarc_countries[saarc_countries$gdp == value, ]
  }
  # Print filtered results
  if (nrow(filtered) == 0) {
    print("No matching countries found.")
  } else {
    print(filtered)
  }
}
# Test the filter function
saarc_filter("population", 100000000) # should return India and Pakistan
saarc_filter("area", 500000) # should return Afghanistan and Nepal
saarc_filter("gdp", 300000000000) # should return India
```
This code creates a data frame containing the SAARC member countries and their ISO codes, and defines two functions: `saarc_search` to search for countries based on name or code, and `saarc_filter` to filter countries based on a given criterion (population, area, or GDP).
