```R
library(shiny)
ui <- fluidPage(
  # Title
  titlePanel("SAARC Member Countries"),
  # Search input
  sidebarLayout(
    sidebarPanel(
      selectInput("search_type", "Search by:", c("Name", "Code")),
      textInput("search_query", "Query:")
    ),
    # Filter inputs
    mainPanel(
