)
server <- function(input, output) {
  # Search function
  search_result <- reactive({
    if (input$search_type == "Name") {
      saarc_countries[saarc_countries$country == input$search_query, ]
    } else {
      saarc_countries[saarc_countries$code == input$search_query, ]
    }
