        print("Warning: Username may be too long.")
    if len(username) <= 8:
        print("Error: Username must be longer than 8 characters.")
    elif not re.search("[A-Z]", username):
        print("Error: Username must contain at least one uppercase letter.")
    elif not re.search("[a-z]", username):
        print("Error: Username must contain at least one lowercase letter.")
    elif not re.search("[0-9]", username):
        print("Error: Username must contain at least one number.")
    elif not re.search("[!@#$%^&*()_+-={};:'\"|,.<>/?]", username):
        print("Error: Username must contain at least one special character.")
    elif re.search("[\\/:*?\"<>| ]", username):
        print("Error: Username must not contain spaces or any of the following characters: \\ / : * ? \" < > |")
    else:
        print("Username is valid.")
# Example usage:
