        {
            Planets = new List<Planet>();
        }
        public void AddPlanet(string name, PlanetType type, AtmosphereType atmosphere, TemperatureType temperature, List<string> moons)
        {
            Planets.Add(new Planet(name, type, atmosphere, temperature, moons));
        }
        public List<Planet> GetPlanetsByType(PlanetType type)
        {
            List<Planet> planets = new List<Planet>();
            foreach (Planet planet in Planets)
