Here is the C# code that implements the above multi-step approach:
```
using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.Threading.Tasks;
using System.IO;
using System.Data;
using System.Windows.Forms.DataVisualization.Charting;
namespace SugarConsumptionAnalysis
{
    class Program
    {
        static void Main(string[] args)
        {
            // Step 1: Data Collection
            DataTable sugarConsumptionData = ReadData("sugar_consumption.csv");
            DataTable healthOutcomeData = ReadData("health_outcomes.csv");
            // Step 2: Data Preprocessing
            sugarConsumptionData = PreprocessData(sugarConsumptionData);
            healthOutcomeData = PreprocessData(healthOutcomeData);
            // Step 3: Merging Data Sets
            DataTable mergedData = MergeData(sugarConsumptionData, healthOutcomeData);
            // Step 4: Calculating Correlation
            Dictionary<string, double> correlations = CalculateCorrelation(mergedData);
            // Step 5: Plotting Scatterplot
            PlotScatterplot(correlations);
        }
        static DataTable ReadData(string fileName)
        {
            DataTable data = new DataTable();
            using (StreamReader reader = new StreamReader(fileName))
            {
                string[] headers = reader.ReadLine().Split(',');
                foreach (string header in headers)
                {
                    data.Columns.Add(header);
                }
                while (!reader.EndOfStream)
                {
                    string[] rows = reader.ReadLine().Split(',');
                    DataRow row = data.NewRow();
                    for (int i = 0; i < headers.Length; i++)
                    {
                        row[i] = rows[i];
                    }
                    data.Rows.Add(row);
                }
            }
            return data;
        }
        static DataTable PreprocessData(DataTable data)
        {
            // Remove missing values
            data = data.Rows.Cast<DataRow>()
                .Where(row => !row.ItemArray.Any(field => field is DBNull))
                .CopyToDataTable();
            // Remove outliers
            double mean = data.AsEnumerable().Average(row => Convert.ToDouble(row.Field<string>("Value")));
            double stdDev = Math.Sqrt(data.AsEnumerable().Average(row => Math.Pow(Convert.ToDouble(row.Field<string>("Value")) - mean, 2)));
            data = data.Rows.Cast<DataRow>()
                .Where(row => Math.Abs(Convert.ToDouble(row.Field<string>("Value")) - mean) < 3 * stdDev)
                .CopyToDataTable();
            return data;
        }
        static DataTable MergeData(DataTable sugarData, DataTable healthData)
        {
            DataTable mergedData = sugarData.Copy();
            mergedData.Columns.Add("Health Outcome");
            foreach (DataRow row in mergedData.Rows)
            {
                DataRow[] matchingRows = healthData.Select(string.Format("Country = '{0}'", row["Country"]));
                if (matchingRows.Length > 0)
                {
                    row["Health Outcome"] = matchingRows[0]["Value"];
                }
            }
            return mergedData;
        }
        static Dictionary<string, double> CalculateCorrelation(DataTable data)
        {
            Dictionary<string, double> correlations = new Dictionary<string, double>();
            foreach (string country in data.AsEnumerable().Select(row => row.Field<string>("Country")).Distinct())
            {
                double[] sugarValues = data.AsEnumerable()
                    .Where(row => row.Field<string>("Country") == country)
                    .Select(row => Convert.ToDouble(row.Field<string>("Sugar Consumption")))
                    .ToArray();
                double[] healthOutcomeValues = data.AsEnumerable()
                    .Where(row => row.Field<string>("Country") == country)
                    .Select(row => Convert.ToDouble(row.Field<string>("Health Outcome")))
                    .ToArray();
                double correlation = CalculateNegativeCorrelation(sugarValues, healthOutcomeValues);
                correlations.Add(country, correlation);
            }
            return correlations;
        }
        static double CalculateNegativeCorrelation(double[] xValues, double[] yValues)
        {
            double xMean = xValues.Average();
            double yMean = yValues.Average();
            double numerator = 0;
            double denominatorX = 0;
            double denominatorY = 0;
            for (int i = 0; i < xValues.Length; i++)
            {
                numerator += (xValues[i] - xMean) * (yValues[i] - yMean);
                denominatorX += Math.Pow(xValues[i] - xMean, 2);
                denominatorY += Math.Pow(yValues[i] - yMean, 2);
            }
            double correlation = numerator / Math.Sqrt(denominatorX * denominatorY);
            return correlation;
        }
        static void PlotScatterplot(Dictionary<string, double> correlations)
        {
            Chart chart = new Chart();
            chart.ChartAreas.Add(new ChartArea());
            foreach (string country in correlations.Keys)
            {
                chart.Series.Add(new Series(country));
                chart.Series[country].ChartType = SeriesChartType.Point;
                chart.Series[country].Points.AddXY(correlations[country], 0);
            }
            chart.Series.Add(new Series("Regression Line"));
            chart.Series["Regression Line"].ChartType = SeriesChartType.Line;
            chart.Series["Regression Line"].Points.AddXY(-1, 0);
            chart.Series["Regression Line"].Points.AddXY(0, 1);
            chart.ChartAreas[0].AxisX.Minimum = -1;
            chart.ChartAreas[0].AxisX.Maximum = 1;
            chart.ChartAreas[0].AxisY.Minimum = 0;
            chart.ChartAreas[0].AxisY.Maximum = 1;
            chart.SaveImage("scatterplot.png", ChartImageFormat.Png);
        }
    }
}
```
