To gather and analyze data on the energy production of nuclear, solar, wind, and hydroelectric power, you can use C# to extract data from various sources, such as government reports, industry publications, and academic journals. Here's a sample code that uses C# to extract data from a CSV file:
```
using System;
using System.IO;
using System.Linq;
class Program
{
    static void Main(string[] args)
    {
        // Read data from CSV file
        var data = File.ReadAllLines("energy_production.csv")
            .Skip(1)
            .Select(x => x.Split(','))
            .Select(x => new
            {
                Type = x[0],
                Capacity = double.Parse(x[1]),
                Production = double.Parse(x[2])
            })
            .ToList();
        // Calculate total energy production for each type
        var totalProduction = data
            .GroupBy(x => x.Type)
            .Select(x => new
            {
                Type = x.Key,
                Production = x.Sum(y => y.Production)
            })
            .ToList();
        // Calculate capacity factor for each type
        var capacityFactor = data
            .Select(x => new
            {
                Type = x.Type,
                Factor = x.Production / (x.Capacity * 8760)
            })
            .GroupBy(x => x.Type)
            .Select(x => new
            {
                Type = x.Key,
                Factor = x.Average(y => y.Factor)
            })
            .ToList();
        // Print results
        Console.WriteLine("Total Energy Production:");
        foreach (var item in totalProduction)
        {
            Console.WriteLine($"{item.Type}: {item.Production} GWh");
        }
        Console.WriteLine("Capacity Factor:");
        foreach (var item in capacityFactor)
        {
            Console.WriteLine($"{item.Type}: {item.Factor:P}");
        }
    }
}
```
